        win_rate_v11 = sum(1 for t in trades_v11 if t > 0) / len(trades_v11) * 100
        avg_trade = np.mean(trades_v11) * 100

        regime_names = {0: 'Saturation', 1: 'Criticité', 2: 'Divergence'}

