def plot_equity(ax, trades, color, label):
    if len(trades) == 0:
        return
    eq = np.cumprod(1 + trades)
    ax.plot((eq - 1) * 100, color=color, linewidth=1.6, label=label)
    ax.axhline(y=0, color='white', linestyle='--', linewidth=0.5, alpha=0.5)

