    resultats['p00'].extend(resultats_mois['p00'].tolist())
    resultats['p05s'].extend(resultats_mois['p05s'].tolist())

    details_mensuels.append({
        'nom':nom, 'regime':regime, 'bh':bh,
        's0':s0, 'sm5':sm5, 's00':s00, 'sp5':sp5,
        'filtre_p00': filtre_info['p00']
    })

    # Indicateur couleur
