    print(f"  {nom:<6} {regime:<10} {s0['ret']:>+8.1f}%{c(s0['ret'])} {sm5['ret']:>+8.1f}%{c(sm5['ret'])} {s00['ret']:>+8.1f}%{c(s00['ret'])} {sp5['ret']:>+8.1f}%{c(sp5['ret'])}  {filtre_info['p00']:>6.1f}% de repos")


